// Create a flaky function that fails randomly
function createFlakyFunction() {
  let callCount = 0;
  const maxFailures = 4; // Will fail 4 times, succeed on the 5th

  return async function flakyOperation() {
    callCount++;
    console.log(`Attempt ${callCount}: Trying flaky operation...`);

    // Fail for the first maxFailures attempts
    if (callCount <= maxFailures) {
      throw new Error('Random failure!');
    }

    console.log('Success! Made it through all retries.');
    return 'Operation completed successfully';
  };
}

