  const flakyFn = createFlakyFunction();

  try {
    // Retry the flaky function with up to 5 attempts
    const result = await retry(flakyFn, { attempts: 5, baseMs: 100 });
    console.log('Final result:', result);
  } catch (error) {
    console.error('All retry attempts failed:', error.message);
  }
}

main().catch(console.error);

