  return new Promise((resolve, reject) => {
    const success = Math.random() > 0.5; // 50% chance of failure
    console.log(success ? '✅ Task succeeded!' : '❌ Task failed...');
    if (success) {
      resolve('Work completed');
    } else {
      reject(new Error('Network timeout')); // Simulate a transient error
    }
  });
}

