  try {
    console.log('Starting retryable task...');
    const result = await retry(flakyTask, { attempts: 5, baseMs: 100 });
    console.log('Final result:', result);
  } catch (err) {
    console.error('Task permanently failed after retries:', err.message);
  }
}

run();
